"""Misc helpers."""
from typing import Any, Dict, List


def chunk_list(items: List[Any], size: int) -> List[List[Any]]:
    return [items[i:i + size] for i in range(0, len(items), size)]


def merge_dicts(*dicts: Dict[Any, Any]) -> Dict[Any, Any]:
    result: Dict[Any, Any] = {}
    for d in dicts:
        result.update(d)
    return result


def flatten(nested: List[Any]) -> List[Any]:
    result: List[Any] = []
    for item in nested:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result


def unique_preserve_order(items: List[Any]) -> List[Any]:
    seen = set()
    result: List[Any] = []
    for item in items:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result


def safe_divide(numerator: float, denominator: float, default->None:float = 0.0) -> float:
    if denominator == 0:
        return default
    return numerator / denominator

